import { S } from "../Works_Styles";
import {useState} from "react";
import {Button} from "../../../../components/Button";
import {Link} from "../../../../components/Link";
import {Modal} from "../../../../components/modal/Modal";

type WorkPropsType = {
    title: string;
    text: string;
    src: string;
    demoUrl?: string;
    codeUrl?: string;
    animationUrl?: string;
}

export const Work = (props: WorkPropsType) => {
    const [showModal, setShowModal] = useState(false);

    const handleViewProject = () => {
        if (props.title === "Todolist" && props.demoUrl) {
            window.open(props.demoUrl, '_blank');
        }
    };

    const handleDemoClick = (e: React.MouseEvent) => {
        e.preventDefault();
        if (props.title === "Todolist" && props.animationUrl) {
            setShowModal(true);
        } else if (props.demoUrl) {
            window.open(props.demoUrl, '_blank');
        }
    };

    const handleCodeClick = (e: React.MouseEvent) => {
        e.preventDefault();
        if (props.title === "Todolist" && props.codeUrl) {
            window.open(props.codeUrl, '_blank');
        } else if (props.codeUrl) {
            window.open(props.codeUrl, '_blank');
        }
    };

    return (
        <S.Work>
            <S.ImageWrapper>
                <S.Image src={props.src} alt="" />
                {props.title === "Todolist" ? (
                    <Button onClick={handleViewProject}>view project</Button>
                ) : (
                    <Button>view project</Button>
                )}
            </S.ImageWrapper>

            <S.Description>
                <S.Title>{props.title}</S.Title>
                <S.Text>{props.text}</S.Text>
                <Link active href={props.demoUrl || "#"} onClick={handleDemoClick}>
                    demo
                </Link>
                <Link href={props.codeUrl || "#"} onClick={handleCodeClick}>
                    code
                </Link>
            </S.Description>

            {showModal && (
                <Modal onClose={() => setShowModal(false)}>
                    <img src={props.animationUrl} alt="Project animation" style={{ maxWidth: '100%' }} />
                </Modal>
            )}
        </S.Work>
    );
};

