import {S} from '../headerMenu/HeaderMenu_Styles';

const items = [
    {
        title: "Main",
        href: "main"
    },
        {
        title: "Skills",
        href: "skills"
    },
    {
        title: "Works",
        href: "works"
    },
    {
        title: "Contact",
        href: "contact"
    },

]

type MenuProps = {
    onClick?: () => void;
};


export const Menu = (props: MenuProps) => {
    return (
        <ul>
            {items.map((item, index) => (
                <S.MenuItem key={index}>
                    <S.NavLink
                        activeClass="active"
                        to={item.href}
                        smooth={true}
                        spy={true}
                        onClick={props.onClick}
                    >
                        {item.title}
                    </S.NavLink>
                </S.MenuItem>
            ))}
        </ul>
    )
}


